TEST_F(utFBXImporterExporter, exportTest) {
    Assimp::Importer importer;
    const aiScene *scene = importer.ReadFile(ASSIMP_TEST_MODELS_DIR "/FBX/apples.fbx", aiProcess_ValidateDataStructure);
    EXPECT_NE(nullptr, scene);
    EXPECT_EQ(scene->mNumMeshes, 10u);
    EXPECT_EQ(scene->mNumTextures, 2u);

    Assimp::Exporter exporter;
    EXPECT_EQ(aiReturn_SUCCESS, exporter.Export(scene, "fbx", ASSIMP_TEST_OUTPUT_DIR "/apples.fbx"));
    // reload and compare
    Assimp::Importer importer2;
    const aiScene *scene2 = importer2.ReadFile(ASSIMP_TEST_OUTPUT_DIR "/apples.fbx", aiProcess_ValidateDataStructure);
    EXPECT_NE(nullptr, scene2);
    EXPECT_EQ(scene->mNumMeshes /*10*/, scene2->mNumMeshes);         mNumMeshes is 0.
    EXPECT_EQ(scene->mNumTextures /*2*/, scene2->mNumTextures);         mNumTextures is 0.
    EXPECT_EQ(scene->mNumMaterials /*2*/, scene2->mNumMaterials);      mNumMaterials is 0.
}
